// Tests for the generated-file ownership gate (lint_generated_drift.go).
//
// The gate's whole value is that it can be trusted, so the false-positive
// classes get as much coverage as the true positive: a fixture project
// carrying an untouched generated file, a heavily edited scaffold-once
// file, a disowned file, a Tier-2-managed starter, and a plain
// hand-written file must ALL pass, while one hand-edited DO-NOT-EDIT file
// must fail with a message that names the file and both remedies.
package lint

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/reliant-labs/forge/internal/checksums"
	"github.com/reliant-labs/forge/internal/generator"
	"github.com/reliant-labs/forge/internal/linter/finding"
)

// writeDriftFile writes content at root/rel, creating parent dirs.
func writeDriftFile(t *testing.T, root, rel, content string) {
	t.Helper()
	full := filepath.Join(root, filepath.FromSlash(rel))
	if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(full, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}

// writeGeneratedPristine writes a Tier-1 file whose embedded marker
// verifies — exactly what `forge generate` leaves behind.
func writeGeneratedPristine(t *testing.T, root, rel, content string) {
	t.Helper()
	stamped, ok := checksums.Stamp(rel, []byte(content))
	if !ok {
		t.Fatalf("%s is not stampable", rel)
	}
	writeDriftFile(t, root, rel, string(stamped))
}

// writeGeneratedHandEdited writes a Tier-1 file whose marker certifies
// `asGenerated` but whose body is `edited` — positive evidence of a
// hand-edit, the same shape a real LLM/user edit leaves.
func writeGeneratedHandEdited(t *testing.T, root, rel, asGenerated, edited string) {
	t.Helper()
	stamped, ok := checksums.StampWithValue(rel, []byte(edited), checksums.BodyHash([]byte(asGenerated)))
	if !ok {
		t.Fatalf("%s is not stampable", rel)
	}
	writeDriftFile(t, root, rel, string(stamped))
}

// TestGeneratedDrift_HandEditedGeneratedFileFails is the true positive:
// the pkg/app/testing.go case that motivated the gate.
func TestGeneratedDrift_HandEditedGeneratedFileFails(t *testing.T) {
	root := t.TempDir()
	const rel = "pkg/app/testing.go"
	writeGeneratedHandEdited(t, root, rel,
		"// Code generated by forge. DO NOT EDIT.\npackage app\n\nfunc NewTestApp() {}\n",
		"// Code generated by forge. DO NOT EDIT.\npackage app\n\nfunc NewTestApp() { /* my tweak */ }\n")

	findings, err := generatedDriftFindings(root)
	if err != nil {
		t.Fatalf("generatedDriftFindings: %v", err)
	}
	if len(findings) != 1 {
		t.Fatalf("findings = %+v, want exactly one", findings)
	}
	f := findings[0]
	if f.Severity != finding.SeverityError {
		t.Errorf("severity = %q, want error (the gate must fail the build)", f.Severity)
	}
	if f.Rule != generatedDriftRule {
		t.Errorf("rule = %q, want %q", f.Rule, generatedDriftRule)
	}
	if f.Path != rel {
		t.Errorf("path = %q, want %q", f.Path, rel)
	}
	// The message must be actionable on its own: name the file, say it is
	// forge-generated, and say the edits are lost on the next generate.
	for _, want := range []string{rel, "DO NOT EDIT", "forge generate", "lost"} {
		if !strings.Contains(f.Message, want) {
			t.Errorf("message missing %q:\n%s", want, f.Message)
		}
	}
	// Both legitimate remedies, by their real command names.
	for _, want := range []string{"git checkout -- " + rel, "forge project disown " + rel, "--reason"} {
		if !strings.Contains(f.Remediation, want) {
			t.Errorf("remediation missing %q:\n%s", want, f.Remediation)
		}
	}

	// And the lane gates on it.
	_, gated, err := collectGeneratedDriftJSON(root)
	if err != nil {
		t.Fatalf("collectGeneratedDriftJSON: %v", err)
	}
	if !gated {
		t.Error("collectGeneratedDriftJSON gated = false; want true")
	}
}

// TestGeneratedDrift_CleanTreePasses: an untouched generated tree — plus
// every non-Tier-1 shape a real project carries — must produce zero
// findings. This is the cry-wolf test.
func TestGeneratedDrift_CleanTreePasses(t *testing.T) {
	root := t.TempDir()

	// A pristine generated file (marker verifies).
	writeGeneratedPristine(t, root, "pkg/app/testing.go",
		"// Code generated by forge. DO NOT EDIT.\npackage app\n\nfunc NewTestApp() {}\n")
	// A scaffold-once ("yours") file — no marker, heavily edited. Forge
	// wrote it once and will never touch it again.
	writeDriftFile(t, root, "pkg/app/setup.go",
		"package app\n\n// entirely rewritten by the user\nfunc Setup() { panic(\"mine\") }\n")
	// A file forge never wrote at all.
	writeDriftFile(t, root, "internal/thing/thing.go", "package thing\n\nfunc Thing() {}\n")

	findings, err := generatedDriftFindings(root)
	if err != nil {
		t.Fatalf("generatedDriftFindings: %v", err)
	}
	if len(findings) != 0 {
		t.Fatalf("clean tree produced findings: %+v", findings)
	}
	if _, gated, err := collectGeneratedDriftJSON(root); err != nil || gated {
		t.Errorf("clean tree: gated=%v err=%v, want a pass", gated, err)
	}
}

// TestGeneratedDrift_EditedScaffoldOncePasses pins the scaffold tier
// explicitly: scaffold-once files are MEANT to be edited, and they carry
// no marker, so the gate can never see them.
func TestGeneratedDrift_EditedScaffoldOncePasses(t *testing.T) {
	root := t.TempDir()
	const rel = "internal/billing/contract.go"
	// As scaffolded, then edited — no forge:hash marker at any point.
	writeDriftFile(t, root, rel, "package billing\n\ntype Service interface{}\n")
	writeDriftFile(t, root, rel, "package billing\n\ntype Service interface{ Charge() error }\n")

	findings, err := generatedDriftFindings(root)
	if err != nil {
		t.Fatalf("generatedDriftFindings: %v", err)
	}
	if len(findings) != 0 {
		t.Fatalf("edited scaffold-once file flagged: %+v", findings)
	}
}

// TestGeneratedDrift_DisownedModifiedPasses: the user took ownership on
// purpose, so their edits are the steady state.
func TestGeneratedDrift_DisownedModifiedPasses(t *testing.T) {
	root := t.TempDir()
	const rel = "pkg/app/wire_gen.go"
	writeGeneratedPristine(t, root, rel,
		"// Code generated by forge. DO NOT EDIT.\npackage app\n\nfunc wire() {}\n")

	cs, err := generator.LoadChecksums(root)
	if err != nil {
		t.Fatal(err)
	}
	if err := cs.DisownPaths(root, []string{rel}, "custom pool wiring"); err != nil {
		t.Fatalf("DisownPaths: %v", err)
	}
	if err := checksums.Save(root, cs); err != nil {
		t.Fatal(err)
	}
	// Edit it hard, after the disown.
	writeDriftFile(t, root, rel, "package app\n\nfunc wire() { /* mine now */ }\n")

	findings, err := generatedDriftFindings(root)
	if err != nil {
		t.Fatalf("generatedDriftFindings: %v", err)
	}
	if len(findings) != 0 {
		t.Fatalf("disowned file flagged: %+v", findings)
	}

	// Belt and braces: even if the user restores a stamped copy from git
	// after disowning, the disown record wins.
	writeGeneratedHandEdited(t, root, rel,
		"// Code generated by forge. DO NOT EDIT.\npackage app\n\nfunc wire() {}\n",
		"// Code generated by forge. DO NOT EDIT.\npackage app\n\nfunc wire() { /* mine */ }\n")
	findings, err = generatedDriftFindings(root)
	if err != nil {
		t.Fatalf("generatedDriftFindings: %v", err)
	}
	if len(findings) != 0 {
		t.Fatalf("disowned record must override a failing marker; got %+v", findings)
	}
}

// TestGeneratedDrift_Tier2ManagedStarterPasses: starters carry a marker
// so `forge project upgrade` can tell pristine from customized — editing
// them is sanctioned, so their drift is not drift.
func TestGeneratedDrift_Tier2ManagedStarterPasses(t *testing.T) {
	root := t.TempDir()
	const rel = "Taskfile.yml"
	if !generator.IsTier2Managed(rel) {
		t.Fatalf("%s is no longer Tier-2-managed; pick another exempt path", rel)
	}
	writeGeneratedHandEdited(t, root, rel, "# as scaffolded\n", "# my tasks\n")

	findings, err := generatedDriftFindings(root)
	if err != nil {
		t.Fatalf("generatedDriftFindings: %v", err)
	}
	if len(findings) != 0 {
		t.Fatalf("sanctioned Tier-2 starter edit flagged: %+v", findings)
	}
}

// TestGeneratedDrift_StaleButPristinePasses is the ordering guarantee:
// a file that is a pristine render of an OLDER template vintage — i.e.
// the user simply hasn't re-run `forge generate` since forge changed —
// self-certifies, so it is never mistaken for a hand-edit.
func TestGeneratedDrift_StaleButPristinePasses(t *testing.T) {
	root := t.TempDir()
	// "Old vintage" is just a pristine stamp of content the current
	// templates would no longer produce; the marker still verifies.
	writeGeneratedPristine(t, root, "pkg/app/app_gen.go",
		"// Code generated by forge. DO NOT EDIT.\npackage app\n\n// v1 shape\ntype App struct{}\n")

	findings, err := generatedDriftFindings(root)
	if err != nil {
		t.Fatalf("generatedDriftFindings: %v", err)
	}
	if len(findings) != 0 {
		t.Fatalf("stale-but-pristine render flagged: %+v", findings)
	}
}

// TestGeneratedDrift_FormatterOnlyChurnPasses: a goimports/gofmt pass
// rewrites bytes without touching meaning. The scan re-hashes after
// canonical formatting, so that must not gate.
func TestGeneratedDrift_FormatterOnlyChurnPasses(t *testing.T) {
	root := t.TempDir()
	writeDriftFile(t, root, "go.mod", "module example.com/demo\n\ngo 1.24\n")

	const rel = "internal/handlers/api/handlers_gen.go"
	canonical := "// Code generated by forge. DO NOT EDIT.\npackage api\n\nimport (\n\t\"fmt\"\n\n\t\"example.com/demo/internal/thing\"\n)\n\nfunc H() { fmt.Println(thing.X) }\n"
	// Stamp the canonical render, then hand the file to a formatter that
	// collapses the import groups (byte drift, zero semantic drift).
	stamped, ok := checksums.Stamp(rel, []byte(canonical))
	if !ok {
		t.Fatalf("%s is not stampable", rel)
	}
	mangled := strings.Replace(string(stamped),
		"\t\"fmt\"\n\n\t\"example.com/demo/internal/thing\"\n",
		"\t\"fmt\"\n\t\"example.com/demo/internal/thing\"\n", 1)
	if mangled == string(stamped) {
		t.Fatal("fixture setup: import regrouping did not change the bytes")
	}
	writeDriftFile(t, root, rel, mangled)

	findings, err := generatedDriftFindings(root)
	if err != nil {
		t.Fatalf("generatedDriftFindings: %v", err)
	}
	if len(findings) != 0 {
		t.Fatalf("formatter-only churn flagged as a hand-edit: %+v", findings)
	}
}

// TestGeneratedDrift_UnverifiedLegacyWarnsButDoesNotGate: the
// legacy-migration sentinel means forge could not ESTABLISH provenance —
// not that it caught an edit. Reporting it is right; gating on it would
// fail whole trees the user never touched.
func TestGeneratedDrift_UnverifiedLegacyWarnsButDoesNotGate(t *testing.T) {
	root := t.TempDir()
	const rel = "pkg/app/app_gen.go"
	stamped, ok := checksums.StampWithValue(rel,
		[]byte("// Code generated by forge. DO NOT EDIT.\npackage app\n"),
		checksums.UnverifiedMarkerValue)
	if !ok {
		t.Fatalf("%s is not stampable", rel)
	}
	writeDriftFile(t, root, rel, string(stamped))

	findings, err := generatedDriftFindings(root)
	if err != nil {
		t.Fatalf("generatedDriftFindings: %v", err)
	}
	if len(findings) != 1 {
		t.Fatalf("findings = %+v, want exactly one", findings)
	}
	if findings[0].Severity != finding.SeverityWarning {
		t.Errorf("severity = %q, want warning (must not gate)", findings[0].Severity)
	}
	if findings[0].Rule != generatedUnverifiedRule {
		t.Errorf("rule = %q, want %q", findings[0].Rule, generatedUnverifiedRule)
	}
	if _, gated, cerr := collectGeneratedDriftJSON(root); cerr != nil || gated {
		t.Errorf("collectGeneratedDriftJSON gated = %v (err %v); want false", gated, cerr)
	}
}

// TestGeneratedDriftJSONShape pins the machine contract: the finding
// lands on the documented lint --json fields (file / severity / rule /
// message / fix_hint) so CI consumers can filter on the rule id.
func TestGeneratedDriftJSONShape(t *testing.T) {
	root := t.TempDir()
	const rel = "pkg/app/testing.go"
	writeGeneratedHandEdited(t, root, rel,
		"// Code generated by forge. DO NOT EDIT.\npackage app\n",
		"// Code generated by forge. DO NOT EDIT.\npackage app\n\n// mine\n")

	fs, gated, err := collectGeneratedDriftJSON(root)
	if err != nil {
		t.Fatalf("collectGeneratedDriftJSON: %v", err)
	}
	if !gated {
		t.Fatal("gated = false, want true")
	}
	report := buildLintJSONReport(fs, gated)
	if report.OK {
		t.Error("report.OK = true; a hand-edited generated file must flip ok to false")
	}
	if report.Summary.Errors != 1 {
		t.Errorf("summary.errors = %d, want 1", report.Summary.Errors)
	}
	blob, err := json.Marshal(report)
	if err != nil {
		t.Fatal(err)
	}
	var decoded struct {
		Findings []struct {
			File     string `json:"file"`
			Severity string `json:"severity"`
			Rule     string `json:"rule"`
			Message  string `json:"message"`
			FixHint  string `json:"fix_hint"`
		} `json:"findings"`
	}
	if err := json.Unmarshal(blob, &decoded); err != nil {
		t.Fatal(err)
	}
	if len(decoded.Findings) != 1 {
		t.Fatalf("decoded findings = %+v, want one", decoded.Findings)
	}
	got := decoded.Findings[0]
	if got.File != rel {
		t.Errorf("file = %q, want %q", got.File, rel)
	}
	if got.Severity != "error" {
		t.Errorf("severity = %q, want %q", got.Severity, "error")
	}
	if got.Rule != generatedDriftRule {
		t.Errorf("rule = %q, want %q", got.Rule, generatedDriftRule)
	}
	if got.Message == "" || got.FixHint == "" {
		t.Errorf("message/fix_hint must both be populated; got %+v", got)
	}
}

// TestGeneratedDriftStepIsGating pins the wiring: plain `forge lint` must
// carry the step, and it must gate. A non-gating entry here would make
// the whole feature a no-op.
func TestGeneratedDriftStepIsGating(t *testing.T) {
	for _, step := range lintPipeline() {
		if step.name != "generated-file drift lint" {
			continue
		}
		if !step.gates {
			t.Fatal("generated-file drift lint must gate the build")
		}
		return
	}
	t.Fatal("generated-file drift lint is not registered in lintPipeline()")
}
